#!/usr/bin/env bash
# Removes files/folders confirmed unused by the Muerta Poker frontend + Godot
# project (verified by grepping every .ts/.tsx/.css/.gd/.tscn/.godot file for
# references — nothing in this list is imported or loaded from anywhere).
#
# Generated by Claude on 2026-09-23. Review the paths below, then run:
#   bash cleanup_unused_files.sh
set -euo pipefail

FRONTEND="/Users/andriinorenko/slot/math-sdk/games/poker_mult_slot/frontend"
GODOT="/Users/andriinorenko/slot/godot-slot"

before=$(du -sh "$FRONTEND" "$GODOT" 2>/dev/null | awk '{s+=$1} END {print s}' || true)

remove() {
  if [ -e "$1" ]; then
    du -sh "$1" 2>/dev/null | awk '{printf "  - %-90s %s\n", $2, $1}'
    rm -rf "$1"
  fi
}

echo "== Frontend: old release zips (22 files, ~295 MB) =="
remove "$FRONTEND/muerta-poker-frontend.zip"
for i in $(seq 2 21); do remove "$FRONTEND/muerta-poker-frontend-v$i.zip"; done
remove "$FRONTEND/cloudy-poker-frontend.zip"

echo "== Frontend: macOS junk + old export dump =="
remove "$FRONTEND/.DS_Store"
remove "$FRONTEND/Claude outputs"

echo "== Frontend: unreferenced asset-pipeline scratch & superseded art =="
remove "$FRONTEND/public/assets/_pack_work"
remove "$FRONTEND/public/assets/cards_handdrawn_backup"
remove "$FRONTEND/public/assets/jorel_pack"
remove "$FRONTEND/public/assets/redesign"
remove "$FRONTEND/public/assets/suits_ornate"
remove "$FRONTEND/public/assets/bg/graffiti-urban.jpg"
remove "$FRONTEND/public/assets/bg/series-gray.png"
remove "$FRONTEND/public/assets/bg/sunny-clouds.png"
remove "$FRONTEND/public/assets/bg/muerta-bg-1.svg"
remove "$FRONTEND/public/assets/ui/fs-cloud.backup.png"
remove "$FRONTEND/public/assets/ui/fs-cloud.puffy.png"
remove "$FRONTEND/public/assets/ui/wood-oak.png"
remove "$FRONTEND/public/assets/ui/wood-walnut.png"

echo "== Godot project: dead scripts (superseded by React HUD / never wired up) =="
remove "$GODOT/scripts/hud.gd"
remove "$GODOT/scripts/hud.gd.uid"
remove "$GODOT/scripts/bunting.gd"
remove "$GODOT/scripts/bunting.gd.uid"
remove "$GODOT/scripts/hand_pays_panel.gd"
remove "$GODOT/scripts/hand_pays_panel.gd.uid"
remove "$GODOT/scripts/demo_driver.gd"
remove "$GODOT/scripts/demo_driver.gd.uid"

echo "== Godot project: dead assets (old in-Godot UI, before it went React-only) =="
remove "$GODOT/assets/bg/muerta_bg.png"
remove "$GODOT/assets/ui/spin_arrow.svg"
remove "$GODOT/assets/ui/spin_button_disabled.png"
remove "$GODOT/assets/ui/spin_button_hover.png"
remove "$GODOT/assets/ui/spin_button_normal.png"
remove "$GODOT/assets/ui/spin_button_pressed.png"

echo
echo "Done."
